// 临时盘点脚本：统计 material-icons 使用情况（用完即删）
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const SKIP = new Set(['node_modules', '.git', 'dist', 'build', '.vscode', 'dev']);
const EXTS = new Set(['.html', '.js', '.css']);

const perFile = [];
const ligatureCount = new Map();
const dynamic = [];

function walk(dir) {
    for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
        if (ent.name.startsWith('.') && ent.name !== '.') continue;
        if (SKIP.has(ent.name)) continue;
        const p = path.join(dir, ent.name);
        if (ent.isDirectory()) { walk(p); continue; }
        if (!EXTS.has(path.extname(ent.name))) continue;
        const rel = path.relative(ROOT, p).replace(/\\/g, '/');
        const src = fs.readFileSync(p, 'utf8');
        const tokens = (src.match(/material-icons/g) || []).length;
        if (!tokens) continue;
        perFile.push({ rel, tokens });

        // 静态：<span class="material-icons ...">ligature</span>
        const re = /class="([^"]*material-icons[^"]*)"[^>]*>\s*([A-Za-z0-9_]+)\s*</g;
        let m;
        while ((m = re.exec(src)) !== null) {
            const name = m[2];
            ligatureCount.set(name, (ligatureCount.get(name) || 0) + 1);
        }
        // 动态：class="...material-icons..." 后面不是纯 ligature 文本
        const re2 = /class="([^"]*material-icons[^"]*)"[^>]*>([\s\S]{0,60}?)</g;
        let m2;
        while ((m2 = re2.exec(src)) !== null) {
            const inner = m2[2].trim();
            if (/^[A-Za-z0-9_]+$/.test(inner) && inner.length) continue;
            const line = src.slice(0, m2.index).split('\n').length;
            dynamic.push(`${rel}:${line}  class="${m1trim(m2[1])}"  inner=${JSON.stringify(inner.slice(0, 50))}`);
        }
    }
}
function m1trim(s) { return s.replace(/\s+/g, ' ').trim(); }

walk(ROOT);

perFile.sort((a, b) => b.tokens - a.tokens);
console.log('=== 每个文件的 material-icons 出现次数 ===');
for (const f of perFile) console.log(String(f.tokens).padStart(5), f.rel);
console.log('总计:', perFile.reduce((s, f) => s + f.tokens, 0));

const lig = [...ligatureCount.entries()].sort((a, b) => b[1] - a[1]);
console.log('\n=== 静态 ligature 名称（' + lig.length + ' 个，共 ' + lig.reduce((s, x) => s + x[1], 0) + ' 处）===');
console.log(lig.map(([n, c]) => `${n}(${c})`).join(' '));

console.log('\n=== 动态/非字面量用法（' + dynamic.length + ' 处）===');
for (const d of dynamic) console.log(d);

