// 解析 woff2 的 cmap，得到每个字重实际包含哪些码点（临时脚本）
import fs from 'node:fs';
import zlib from 'node:zlib';

const KNOWN_TAGS = ['cmap','head','hhea','hmtx','maxp','name','OS/2','post','cvt ','fpgm','glyf','loca','prep','CFF ','VORG','EBDT','EBLC','gasp','hdmx','kern','LTSH','PCLT','VDMX','vhea','vmtx','BASE','GDEF','GPOS','GSUB','EBSC','JSTF','MATH','CBDT','CBLC','COLR','CPAL','SVG ','sbix','acnt','avar','bdat','bloc','bsln','cvar','fdsc','feat','fmtx','fvar','gvar','hsty','just','lcar','mort','morx','opbd','prop','trak','Zapf','Silf','Glat','Gloc','Feat','Sill'];

function readUIntBase128(buf, pos) {
    let result = 0;
    for (let i = 0; i < 5; i++) {
        const b = buf[pos++];
        if (i === 0 && b === 0x80) throw new Error('invalid base128');
        result = (result << 7) | (b & 0x7f);
        if (result > 0xffffffff) throw new Error('overflow');
        if ((b & 0x80) === 0) return { value: result >>> 0, pos };
    }
    throw new Error('base128 too long');
}

function parseCmap(buf) {
    const numTables = buf.readUInt16BE(2);
    let best = null;
    for (let i = 0; i < numTables; i++) {
        const off = 4 + i * 8;
        const platform = buf.readUInt16BE(off);
        const encoding = buf.readUInt16BE(off + 2);
        const subOff = buf.readUInt32BE(off + 4);
        const format = buf.readUInt16BE(subOff);
        const rank = (format === 12 && platform === 3 && encoding === 10) ? 3
            : (format === 4 && platform === 3 && encoding === 1) ? 2
            : (format === 4 || format === 12) ? 1 : 0;
        if (rank && (!best || rank > best.rank)) best = { rank, subOff, format };
    }
    const cps = new Set();
    if (!best) return cps;
    const p = best.subOff;
    if (best.format === 4) {
        const segX2 = buf.readUInt16BE(p + 6);
        const seg = segX2 / 2;
        const endO = p + 14, startO = endO + segX2 + 2, deltaO = startO + segX2, rangeO = deltaO + segX2;
        for (let s = 0; s < seg; s++) {
            const end = buf.readUInt16BE(endO + s * 2);
            const start = buf.readUInt16BE(startO + s * 2);
            const delta = buf.readInt16BE(deltaO + s * 2);
            const rangeOff = buf.readUInt16BE(rangeO + s * 2);
            if (start === 0xffff) continue;
            for (let c = start; c <= end; c++) {
                let gid;
                if (rangeOff === 0) gid = (c + delta) & 0xffff;
                else {
                    const gi = rangeO + s * 2 + rangeOff + (c - start) * 2;
                    if (gi + 1 >= buf.length) continue;
                    gid = buf.readUInt16BE(gi);
                    if (gid !== 0) gid = (gid + delta) & 0xffff;
                }
                if (gid !== 0) cps.add(c);
            }
        }
    } else if (best.format === 12) {
        const nGroups = buf.readUInt32BE(p + 12);
        for (let g = 0; g < nGroups; g++) {
            const o = p + 16 + g * 12;
            const start = buf.readUInt32BE(o), end = buf.readUInt32BE(o + 4);
            for (let c = start; c <= end && c - start < 0x10000; c++) cps.add(c);
        }
    }
    return cps;
}

function woff2Cmap(file) {
    const buf = fs.readFileSync(file);
    if (buf.toString('latin1', 0, 4) !== 'wOF2') throw new Error('not woff2: ' + file);
    const numTables = buf.readUInt16BE(12);
    const totalCompressedSize = buf.readUInt32BE(24);
    let pos = 48;
    const tables = [];
    for (let i = 0; i < numTables; i++) {
        const flags = buf[pos++];
        const idx = flags & 0x3f;
        const tv = (flags >> 6) & 0x03;
        let tag;
        if (idx === 63) { tag = buf.toString('latin1', pos, pos + 4); pos += 4; }
        else tag = KNOWN_TAGS[idx];
        const o = readUIntBase128(buf, pos); pos = o.pos;
        const origLength = o.value;
        let transformLength = null;
        const isGlyfLoca = tag === 'glyf' || tag === 'loca';
        const hasTransform = isGlyfLoca ? tv !== 3 : tv !== 0;
        if (hasTransform) { const t = readUIntBase128(buf, pos); pos = t.pos; transformLength = t.value; }
        tables.push({ tag, origLength, transformLength });
    }
    const compressed = buf.subarray(pos, pos + totalCompressedSize);
    const raw = zlib.brotliDecompressSync(compressed);
    let off = 0, cmapBuf = null;
    for (const t of tables) {
        const len = t.transformLength !== null ? t.transformLength : t.origLength;
        if (t.tag === 'cmap') cmapBuf = raw.subarray(off, off + t.origLength);
        off += len;
    }
    if (!cmapBuf) throw new Error('no cmap in ' + file);
    return parseCmap(cmapBuf);
}

const styles = {
    regular: '_fa_probe/webfonts_fa-regular-400.woff2',
    light: '_fa_probe/webfonts_fa-light-300.woff2',
    thin: '_fa_probe/webfonts_fa-thin-100.woff2',
    solid: '_fa_probe/webfonts_fa-solid-900.woff2'
};
const out = {};
for (const [name, file] of Object.entries(styles)) {
    const cps = woff2Cmap(file);
    out[name] = [...cps].sort((a, b) => a - b);
    console.log(`${name.padEnd(8)} 码点数 ${cps.size}  范围 U+${Math.min(...cps).toString(16)} - U+${Math.max(...cps).toString(16)}`);
}
fs.writeFileSync('_fa_probe/availability.json', JSON.stringify(out));
console.log('written _fa_probe/availability.json');

