@property --fire-angle {
    syntax: '<angle>';
    initial-value: 0deg;
    inherits: false;
}

@keyframes fire-flow-angle {
    0%   { --fire-angle: 0deg; }
    100% { --fire-angle: 360deg; }
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    /* Roboto 由 js/cdn-styles.js 异步加载；加载前/失败时回退到系统字体，
