    padding: 3px;
    border-radius: 8px;
    gap: 4px;
}

.tab-btn {
    flex: 1;
    border: none;
    background: transparent;
    padding: 8px 0;
    border-radius: 6px;
    color: #64748b;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
}

/* Tab 图标统一使用 FontAwesome（线性 fa-regular / 实心 fa-solid） */
.tab-btn .fa-solid,
