}

.dark .ai-model-select-item .model-src,
.theme-dark .ai-model-select-item .model-src {
    color: #64748b;
}

.dark .ai-model-select-count,
.theme-dark .ai-model-select-count {
    color: #64748b;
}

.dark .ai-model-select-empty,
.theme-dark .ai-model-select-empty {
