/* AI 提供商卡片列表 */
.ai-card-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.ai-card {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 12px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    transition: all 0.2s;
    cursor: pointer;
    position: relative;
    overflow: hidden;
}
.ai-card .mi,
.ai-card .fa-regular {
    font-size: 12px;
    vertical-align: middle;
}

.ai-card::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 10px;
    padding: 1.5px;
    background: conic-gradient(
        from var(--fire-angle, 0deg),
        transparent,
        transparent,
        #ff4500,
        #ff8c00,
        #ffd700,
        #ff6b00,
        #ff4500,
        transparent,
        transparent
    );
    -webkit-mask:
        linear-gradient(#fff 0 0) content-box,
        linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask:
        linear-gradient(#fff 0 0) content-box,
        linear-gradient(#fff 0 0);
    mask-composite: exclude;
    z-index: 0;
    opacity: 0;
    transition: opacity 0.4s ease;
    animation: fire-flow-angle 2.5s linear infinite;
    pointer-events: none;
}

.ai-card:hover {
    border-color: transparent;
    box-shadow: 0 2px 8px rgba(99, 102, 241, 0.08);
}
.ai-card:hover::before {
    opacity: 1;
}
.ai-card > * {
    position: relative;
    z-index: 2;
}
.ai-card.dragging {
    opacity: 0.5;
    border-style: dashed;
}
.ai-card.drag-over {
    border-color: #8b5cf6;
    border-style: dashed;
    background: #f5f3ff;
}

