/* === 服务器管理模块样式 === */
#view-servers {
    display: flex;
    flex-direction: row;
    gap: 0;
    padding: 0;
    height: 100%;
    min-height: 0;
    overflow: hidden;
}

#view-servers.hidden {
    display: none;
}

/* 左侧分类侧边栏 */
.srv-sidebar {
    width: 48px;
    background: #f1f5f9;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 10px 0;
    border-radius: 12px;
    margin: 8px 0 8px 8px;
    flex-shrink: 0;
    overflow: hidden;
    position: sticky;
    top: 0;
    z-index: 2;
    gap: 8px;
    height: fit-content;
}

.srv-cat-tab {
    width: 34px;
    height: 34px;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.2s;
    color: #94a3b8;
    gap: 1px;
    flex-shrink: 0;
}

.srv-cat-tab .mi,
.srv-cat-tab .fa-folder,
.srv-cat-tab .fa-folder-open {
    font-size: 15px;
}

.srv-cat-label {
    font-size: 8px;
    line-height: 1;
    text-align: center;
    max-width: 30px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 500;
}

.srv-cat-tab:hover {
    background: #e2e8f0;
    color: #475569;
}

.srv-cat-tab.active {
    background: #fff;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
    color: #6366f1;
}

.srv-cat-tab.active .mi,
.srv-cat-tab.active .fa-folder,
.srv-cat-tab.active .fa-folder-open {
    color: #f59e0b;
}

/* 拖拽排序位置标识 */
.srv-cat-tab.dragging {
    opacity: 0.4;
    transform: scale(0.9);
}

.srv-cat-tab.drag-over {
    border-top: 2px solid #6366f1;
    margin-top: -1px;
    border-radius: 0;
}

/* 右侧主内容区 — 独立滚动 */
.srv-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0;
    padding-bottom: 0;
    min-width: 0;
    padding-left: 8px;
    overflow: hidden;
    min-height: 0;
}

/* 服务器列表滚动区（头部 + 列表，独立滚动） */
#srv-scroll {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    padding-bottom: 6px;
}

/* 分类管理弹窗列表 */
.srv-cat-list {
    display: flex;
    flex-direction: column;
    gap: 4px;
    max-height: 300px;
    overflow-y: auto;
}

.srv-cat-list-item {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 10px;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    cursor: default;
    transition: all 0.2s;
    user-select: none;
}

.srv-cat-list-item:hover {
    background: #f1f5f9;
    border-color: #cbd5e1;
}

.srv-cat-list-item.dragging {
    opacity: 0.4;
    border-style: dashed;
    background: #e2e8f0;
}

.srv-cat-list-item.drag-over {
    border-top: 2px solid #6366f1;
    margin-top: -1px;
}

.srv-cat-drag-handle {
    color: #cbd5e1;
    cursor: grab;
    font-size: 18px;
    flex-shrink: 0;
    transition: color 0.2s;
}

.srv-cat-drag-handle:hover {
    color: #6366f1;
}

.srv-cat-list-item:active .srv-cat-drag-handle {
    cursor: grabbing;
}

.srv-cat-list-name {
    flex: 1;
    font-size: 13px;
    color: #334155;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.srv-cat-list-actions {
    display: flex;
    gap: 4px;
    flex-shrink: 0;
}

.srv-cat-list-actions .mi {
    font-size: 16px;
    color: #cbd5e1;
    cursor: pointer;
    transition: color 0.2s;
    padding: 2px;
}

.srv-cat-list-actions .mi:hover {
    color: #6366f1;
}

.srv-cat-list-actions .srv-cat-del-icon:hover {
    color: #ef4444;
}

/* 暗色：分类管理弹窗 */
.dark .srv-cat-list-item,
.theme-dark .srv-cat-list-item {
    background: #1e293b;
    border-color: #334155;
}

.dark .srv-cat-list-item:hover,
.theme-dark .srv-cat-list-item:hover {
    background: #0f172a;
    border-color: #475569;
}

.dark .srv-cat-list-name,
.theme-dark .srv-cat-list-name {
    color: #e2e8f0;
}

.dark .srv-cat-drag-handle,
.theme-dark .srv-cat-drag-handle {
    color: #475569;
}

/* 命令按钮行 + 计数栏：固定在顶部，不随卡片滚动 */
#srv-header {
    position: sticky;
    top: 0;
    z-index: 10;
    background: #f8fafc;
    padding: 4px 0 6px 0;
}

#srv-controls {
    margin-bottom: 4px;
}

/* 服务器总数计数栏 */
.srv-count-bar {
    font-size: 11px;
    color: #94a3b8;
    padding: 0 2px;
    line-height: 1.4;
}

/* 收费统计栏（固定于列表底部，独立于滚动区） */
.srv-money-bar {
    flex-shrink: 0;
    background: #f8fafc;
    padding: 6px 2px;
    border-top: 1px solid #e2e8f0;
}

.srv-money-bar .srv-money-paid {
    color: #10b981;
}

.srv-money-bar .srv-money-unpaid {
    color: #ef4444;
}

/* 搜索栏：默认收起为图标按钮，点击展开全宽搜索 */
#srv-filter-row {
    display: none;
    flex: 1;
    align-items: center;
    gap: 4px;
    padding: 0;
    height: 24px;
}

#srv-filter-row input {
    padding-top: 2px !important;
    padding-bottom: 2px !important;
}

#srv-controls.search-active #srv-cmd-group,
#srv-controls.search-active #srv-search-toggle {
    display: none;
}

#srv-controls.search-active #srv-filter-row {
    display: flex;
}

/* 暗色：搜索返回箭头 */
.dark #srv-search-back,
.theme-dark #srv-search-back {
    color: #94a3b8;
}

.srv-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

/* 服务器卡片 */
.srv-card {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    padding: 12px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    transition: all 0.2s;
    position: relative;
}

.srv-card:hover {
    border-color: #6366f1;
    box-shadow: 0 2px 8px rgba(99, 102, 241, 0.08);
}

.srv-card.dragging {
    opacity: 0.4;
    border-style: dashed;
    transform: scale(0.97);
}

.srv-card.drag-over {
    border-color: #6366f1;
    background: #eef2ff;
    box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.2);
}

.srv-card-header {
    display: flex;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    user-select: none;
}

.srv-card-toggle {
    font-size: 18px;
    color: #94a3b8;
    transition: transform 0.3s ease;
    transform: rotate(0deg);
}

.srv-card.expanded .srv-card-toggle {
    transform: rotate(180deg);
}

.srv-card-name {
    font-size: 13px;
    font-weight: 600;
    color: #1e293b;
    font-family: monospace;
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.srv-card-badge {
    font-size: 10px;
    font-weight: 500;
    padding: 2px 6px;
    border-radius: 4px;
    background: #f1f5f9;
    color: #64748b;
    border: 1px solid #e2e8f0;
    white-space: nowrap;
}

.srv-card-actions {
    display: flex;
    gap: 6px;
    flex-shrink: 0;
}

.srv-card-actions .mi,
.srv-card-actions .fa-xmark {
    font-size: 16px;
    color: #cbd5e1;
    cursor: pointer;
    transition: color 0.2s;
}

.srv-card-actions .mi:hover,
.srv-card-actions .fa-xmark:hover {
    color: #6366f1;
}

.srv-card-actions .srv-del-btn:hover {
    color: #ef4444;
}

/* 卡片展开内容 */
.srv-card-body {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding-top: 8px;
    border-top: 1px solid #f1f5f9;
}

.srv-info-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 12px;
    padding: 3px 0;
}

.srv-info-label {
    color: #94a3b8;
    white-space: nowrap;
    margin-right: 8px;
    flex-shrink: 0;
}

.srv-info-val {
    color: #334155;
    text-align: right;
    word-break: break-all;
    font-family: monospace;
}

.srv-info-val.srv-masked {
    color: #94a3b8;
}

/* 单行点击复制 */
.srv-copy-row {
    cursor: pointer;
    border-radius: 4px;
    padding: 3px 4px;
    margin: 0 -4px;
    transition: background 0.2s;
}

.srv-copy-row:hover {
    background: #f1f5f9;
}

/* 表单标签栏（label + 开关并排） */
.srv-form-label-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

/* WP 开关 */
.srv-wp-switch {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    cursor: pointer;
    font-size: 11px;
    color: #64748b;
    user-select: none;
}

.srv-wp-switch input {
    display: none;
}

.srv-wp-slider {
    width: 28px;
    height: 15px;
    background: #cbd5e1;
    border-radius: 8px;
    position: relative;
    transition: background 0.2s;
    flex-shrink: 0;
}

.srv-wp-slider::after {
    content: '';
    position: absolute;
    top: 1.5px;
    left: 1.5px;
    width: 12px;
    height: 12px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s;
    box-shadow: 0 1px 2px rgba(0,0,0,0.15);
}

.srv-wp-switch input:checked + .srv-wp-slider {
    background: #6366f1;
}

.srv-wp-switch input:checked + .srv-wp-slider::after {
    transform: translateX(13px);
}

/* 禁用态（未开启收费时已收款开关置灰） */
.srv-wp-switch input:disabled + .srv-wp-slider {
    opacity: 0.55;
}

.srv-wp-switch:has(input:disabled) {
    cursor: not-allowed;
}

/* 分区标题栏 */
.srv-section-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin: 8px 0 4px;
    padding-bottom: 4px;
    border-bottom: 1px solid #e2e8f0;
}

.srv-section-title {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 12px;
    font-weight: 600;
    color: #475569;
}

/* 输入框内嵌按钮 */
.srv-input-wrap {
    position: relative;
}
.srv-input-wrap input {
    padding-right: 32px;
}
.srv-input-wrap:has(.srv-input-actions) input {
    padding-right: 56px;
}
/* 结果框(div)也需要给右侧按钮让位 */
.srv-input-wrap > .result-box {
    padding-right: 32px;
}
/* 带内嵌复制按钮的数字输入框：隐藏会与按钮重叠的原生微调箭头（Chrome 中箭头绘制在最右侧 padding 区） */
.srv-input-wrap input[type="number"]::-webkit-inner-spin-button,
.srv-input-wrap input[type="number"]::-webkit-outer-spin-button {
    -webkit-appearance: none;
    margin: 0;
}
.srv-input-actions {
    position: absolute;
    right: 4px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    align-items: center;
    gap: 2px;
}
.srv-icopy-btn,
.tool-icopy-btn {
    position: absolute;
    right: 4px;
    top: 50%;
    transform: translateY(-50%);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    border: none;
    background: transparent;
    color: #94a3b8;
    cursor: pointer;
    border-radius: 4px;
    transition: all 0.15s;
    padding: 0;
    line-height: 1;
}
.srv-input-actions .srv-icopy-btn {
    position: static;
    transform: none;
}
.srv-icopy-btn:hover,
.tool-icopy-btn:hover {
    color: #6366f1;
    background: rgba(99, 102, 241, 0.08);
}
.srv-icopy-btn:active,
.tool-icopy-btn:active {
    transform: translateY(-50%) scale(0.9);
}
.srv-input-actions .srv-icopy-btn:active {
    transform: scale(0.9);
}
/* 复制成功后的短暂反馈 */
.tool-icopy-btn.copied {
    color: #16a34a;
    background: rgba(22, 163, 74, 0.12);
}
.dark .srv-icopy-btn,
.theme-dark .srv-icopy-btn,
.dark .tool-icopy-btn,
.theme-dark .tool-icopy-btn {
    color: #64748b;
}
.dark .srv-icopy-btn:hover,
.theme-dark .srv-icopy-btn:hover,
.dark .tool-icopy-btn:hover,
.theme-dark .tool-icopy-btn:hover {
    color: #818cf8;
    background: rgba(129, 140, 248, 0.12);
}

/* 一键复制按钮 */
.srv-copy-btn {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    font-size: 11px;
    padding: 3px 8px;
    border-radius: 6px;
    border: 1px solid #c7d2fe;
    background: #eef2ff;
    color: #4338ca;
    cursor: pointer;
    transition: all 0.15s;
    white-space: nowrap;
    line-height: 1;
}

.srv-copy-btn:hover {
    background: #6366f1;
    border-color: #6366f1;
    color: #fff;
}

.srv-copy-btn:active {
    transform: scale(0.95);
}

/* 网站区块 */
.srv-ws-section {
    margin-top: 6px;
    padding-top: 8px;
    border-top: 1px dashed #e2e8f0;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.srv-ws-header {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 12px;
    font-weight: 600;
