left: 8px;
top: 50%;
transform: translateY(-50%);
font-size: 16px;
color: #94a3b8;
pointer-events: none;
}

/* 当搜索框前有按钮时，调整搜索图标位置（仅 prompts 搜索框） */
#search-group-prompts .search-icon-overlay {
left: 42px;
}
#search-group-prompts .search-input {
padding-left: 30px;
