/* ---------- 上下同步编辑区（textarea + 高亮背板） ---------- */
.code-area {
    position: relative;
    flex: 1;
    min-height: 0;
    overflow: hidden;
    background: #fcfdff;
    --code-gutter: 0px;
}

.code-area.has-gutter {
