}

/* 行号槽（仅 HTML 编辑器） */
.code-gutter {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--code-gutter);
    overflow: hidden;
    background: #f4f6fb;
    border-right: 1px solid #e6ebf2;
    z-index: 0;
    pointer-events: none;
}

.code-gutter-inner {
    position: absolute;
    left: 0;
    top: 0;
    right: 0;
    will-change: transform;
}

.code-ln {
    position: absolute;
    right: 7px;
    font-family: ui-monospace, 'Roboto Mono', Consolas, 'Courier New', monospace;
    font-size: 12px;
    line-height: 18px;
    color: #a3b0c2;
    user-select: none;
}

.code-backdrop,
.code-textarea {
    position: absolute;
    inset: 0 0 0 var(--code-gutter);
    margin: 0;
    padding: 8px 10px;
    font-family: ui-monospace, 'Roboto Mono', Consolas, 'Courier New', monospace;
    font-size: 12px;
    line-height: 18px;
    white-space: pre-wrap;
    overflow-wrap: break-word;
    word-break: break-word;
    tab-size: 2;
    border: none;
    outline: none;
}

.code-backdrop {
    z-index: 0;
    color: #334155;
    background: #fcfdff;
    overflow-y: scroll;
    overflow-x: hidden;
    pointer-events: none;
    scrollbar-gutter: stable;
}

/* 上面的通用选择器 * { font-family: 'Roboto', sans-serif } 会覆盖 span 从
   .code-backdrop 继承来的等宽字体：高亮窗口里的 token 会用比例字体渲染，
   于是"看到的文字"和 textarea（真正接收光标/鼠标的那一层）对不上，
   表现为光标本符、鼠标点在文字上却落在别的字符处。这里强制等宽度量。 */
.code-backdrop * {
    font-family: inherit;
    font-size: inherit;
    line-height: inherit;
    letter-spacing: inherit;
    word-spacing: inherit;
    font-variant: inherit;
    font-stretch: inherit;
    text-transform: inherit;
    white-space: inherit;
    tab-size: inherit;
}

.code-textarea {
    z-index: 1;
    color: transparent;
    caret-color: #4f46e5;
    background: transparent;
    overflow-y: auto;
    overflow-x: hidden;
    resize: none;
    scrollbar-gutter: stable;
}

.code-textarea::selection {
    background: rgba(99, 102, 241, .25);
}

.code-textarea::placeholder {
