}

.fuel-updated {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 11px;
    color: #a8a29e;
}


/* === 实时汇率样式 === */
.exchange-input-row {
    display: flex;
    gap: 8px;
    align-items: center;
