    border-top: 1px dashed #a5f3fc;
}

.exchange-item {
    background: #f0fdfa;
    border: 1px solid #a5f3fc;
    border-radius: 6px;
    padding: 6px 8px;
    display: flex;
    justify-content: space-between;
