/* === 热门榜单样式 === */
.view-hot-flex {
    display: flex;
    flex-direction: row;
    padding: 0;
}

.hot-sidebar {
    width: 60px;
    background: #f1f5f9;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 10px 0;
    margin: 8px 0 8px 8px;
