}

.hot-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.hot-item {
    display: flex;
    gap: 10px;
    padding: 10px;
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s;
