    flex-direction: column;
    gap: 4px;
    overflow: hidden;
}

.hot-title {
    font-size: 13px;
    font-weight: 500;
    color: #334155;
    line-height: 1.4;
    display: -webkit-box;
    -webkit-line-clamp: 2;
