    }
}

/* === 国际时钟样式 === */
.clock-container {
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.main-clock-card {
    /* iOS Liquid Glass (White/Transparent) */
    background: rgba(255, 255, 255, 0.25);
    border-radius: 20px;
    padding: 16px;
    /* Reduced from 24px */
    color: #334155;
    /* Dark text for light background */
    text-align: center;
    box-shadow:
        0 4px 30px rgba(0, 0, 0, 0.1),
        inset 0 0 20px rgba(255, 255, 255, 0.5);
    /* Inner glow for liquid effect */
    border: 1px solid rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    position: relative;
    overflow: hidden;
    margin-bottom: 5px;
}

/* Optional: Add a subtle shine effect */
.main-clock-card::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(255, 255, 255, 0.4) 0%, transparent 70%);
    pointer-events: none;
    transform: rotate(30deg);
}

.main-clock-card .main-time {
    font-size: 48px;
    font-weight: 700;
    margin: 0;
    font-family: 'Roboto Mono', monospace;
    letter-spacing: 2px;
    line-height: 1.1;
    /* Tighter line height to reduce height */
    text-shadow: 0 1px 2px rgba(255, 255, 255, 0.8);
    /* White shadow for depth on dark text */
    color: #4f46e5;
    /* Primary brand color for time */
}

