    border: 1px solid #c7d2fe;
    background: #eef2ff;
    color: #4f46e5;
    font-size: 11px;
    font-weight: 500;
    font-family: inherit;
    line-height: 1.5;
    cursor: pointer;
    transition: all 0.2s;
    white-space: nowrap;
}

.ai-fetch-models-btn:hover:not(:disabled) {
    background: #e0e7ff;
    border-color: #a5b4fc;
}

.ai-fetch-models-btn:disabled {
