    font-size: 12px;
    color: #334155;
    word-break: break-all;
}

.ai-model-select-item .model-src {
    flex-shrink: 0;
    font-size: 10px;
    color: #94a3b8;
    max-width: 100px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ai-model-select-item .model-state {
    flex-shrink: 0;
    font-size: 10px;
    color: #10b981;
    white-space: nowrap;
}

.ai-model-select-count {
    margin-top: 6px;
    text-align: right;
    font-size: 11px;
    color: #94a3b8;
}

